import heapq


def shortest_path(graph, src, dst):
    if src == dst:
        return [src]

    best = {src: (0, (src,))}
    heap = [(0, (src,), src)]

    while heap:
        distance, path, node = heapq.heappop(heap)

        if best.get(node) != (distance, path):
            continue

        if node == dst:
            return list(path)

        for neighbor, weight in graph.get(node, {}).items():
            new_distance = distance + weight
            new_path = path + (neighbor,)
            current = best.get(neighbor)

            if (
                current is None
                or new_distance < current[0]
                or (new_distance == current[0] and new_path < current[1])
            ):
                best[neighbor] = (new_distance, new_path)
                heapq.heappush(heap, (new_distance, new_path, neighbor))

    return []
